import {paintStudy} from './colour-raster.js?v=r1';
// The manual specifies names and SF codes, not RGB. These are display interpretations.
export const displayPalette={SF01:'#c9cdd5',SF03:'#c49a42',SF10:'#c92329',SF13:'#ba641f',SF17:'#354fa0',SF20:'#142c50',SF25:'#c5a589',SF26:'#612c78',SF32:'#202124'};
const names={SF01:'Silver',SF03:'Gold',SF10:'Red',SF13:'Tenne',SF17:'Ultramarine',SF20:'Midnight',SF25:'Nude hosiery',SF26:'Purple',SF32:'Black'};
const divisions={command:{name:'Command',code:'SF13'},sciences:{name:'Sciences',code:'SF17'},engineering:{name:'Engineering / support',code:'SF10'}};
const ranks={ensign:[],lieutenant:[1],'lieutenant-commander':[1,0],commander:[1,1],captain:[1,0,1],commodore:[1,1,1],admiral:[1,1,1,1]};
const titleCase=s=>s.split('-').map(w=>w[0].toUpperCase()+w.slice(1)).join(' ');
export const plates=[
 {id:'ufp-banner',kind:'banner',category:'flags',title:'United Federation banner',sub:'Thirteen stars. One Federation.',page:35,to:'00:02:00',codes:['SF10','SF01'],note:'The white field in the drawing is specified red; the stars and elongated UFP monogram are silver. This is the manual’s tall, thirteen-star swallowtail design.'},
 {id:'ufp-seal',kind:'seal',category:'flags',title:'United Federation seal',sub:'The historic celestial seal.',page:36,to:'00:02:01',codes:['SF20','SF01'],note:'The circular celestial chart, wreath and UFP lettering are silver on a blue ground. The sheet calls SF20UC “Blue”; the colour table names the same code “Midnight”.'},
 {id:'alpha-centauri',kind:'centauri',category:'flags',title:'Alpha Centauri pennant',sub:'Gold on a purple field.',page:45,to:'00:02:10',codes:['SF26','SF03'],note:'A sword-bearing centaur, surrounding discs and stars, and the pennant border are specified gold. The ground is purple. Fine contours are reconstructed from the printed drawing.'},
 ...Object.entries(divisions).map(([id,d])=>({id:`${id}-badge`,kind:'badge',division:id,category:'insignia',title:`${d.name} insignia`,sub:'Gold ground / black device.',page:65,to:'01:03:00',codes:['SF03','SF32'],note:'All three division badges share a gold ground and black outline. Division is identified by the central device, not by changing the badge colour. The asymmetric delta follows the manual silhouette.'})),
 {id:'male-duty',kind:'uniform',category:'uniforms',title:'Duty uniform / male',sub:'Front, side and back, in division colours.',page:66,to:'01:03:10',codes:['SF13','SF32','SF03'],note:'The manual’s own front, side and back figures (PDF 66), coloured by region: division tunic, black neckband, service trousers and boots. The source figure is an ensign; other grades add the gold braid drawn on PDF 65, placed above each cuff. The division insignia is the PDF 65 badge set at the drawn D.I. position. Faces and hands are left as drawn.'},
 {id:'female-duty',kind:'uniform',category:'uniforms',title:'Duty uniform / female',sub:'Officers and ensigns.',page:70,to:'01:03:14',codes:['SF17','SF32','SF25','SF03'],note:'The manual’s own figures (PDF 70), coloured by region: fitted division tunic, black collar and boots, and SF25 “Nude” pantyhose — the specification describes hosiery, not skin. The source figure is an ensign; officer grades add the PDF 65 braid above each cuff. Medical exceptions are outside this study.'}
];
// Studies are the manual's own drawings, colourised on a canvas (see colour-raster.js); nothing is redrawn as vectors.
export function artwork(item,{division=item.division||(item.id==='female-duty'?'sciences':'command'),rank='ensign'}={}){const label=`${item.title}${item.kind==='uniform'?`, ${divisions[division].name}, ${titleCase(rank)}`:''} — colourised from the Star Fleet Technical Manual`;return `<canvas class="colour-art" data-study="${item.id}" data-division="${division}" data-rank="${rank}" role="img" aria-label="${label}"></canvas>`;}
export function paintArt(root,p){root.querySelectorAll('canvas[data-study]').forEach(c=>{const item=plates.find(x=>x.id===c.dataset.study);if(!item)return;const d=c.dataset.division;let spec;
 if(item.kind==='uniform')spec={id:item.id,kind:'uniform',division:d,rank:c.dataset.rank,colours:{tunic:p[divisions[d].code],black:p.SF32,hose:p.SF25,badge:p.SF03,gold:p.SF03}};
 else if(item.kind==='badge')spec={id:`${item.division}-badge`,kind:'badge',colours:{badge:p.SF03,device:p.SF32}};
 else spec={id:item.id,kind:'flag',colours:{field:p[item.codes[0]],metal:p[item.codes[1]]}};
 paintStudy(c,spec).catch(e=>{console.error(e);c.replaceWith(Object.assign(document.createElement('p'),{className:'small',textContent:'This colour study could not load.'}));});});}
const sourceUrl=p=>`assets/colours/page-${p}.webp`;
const swatches=(codes,p)=>codes.map(code=>`<div class="colour-spec"><i style="background:${p[code]}"></i><span>${names[code]}<small>${code}UC</small></span></div>`).join('');
export function renderColours(main,path){
 let alive=true,scan=null,mode='rendered',category='all',division='command',rank='ensign';
 const item=plates.find(x=>x.id===path.split('/')[2]);if(item?.id==='female-duty')division='sciences';
 const folio=`<div class="folio"><span><a href="#/">COMMAND SECTION</a> / <a href="#/colours">COLOUR PLATES</a></span><span>STAR FLEET SPECIFICATION / SF–UC</span></div>`;
 const modeControl=`<label class="colour-mode">DISPLAY <select id="colour-mode"><option value="rendered">Named-colour reconstruction</option><option value="scan" disabled>Scan samples · loading</option></select></label>`;
 const method=`<aside class="colour-method"><strong>Reading the colour specification</strong><p>The manual assigns names and SF codes, not RGB values. These drawings follow those assignments; screen hues, shading and materials are reconstructions. The scan’s colour chart is visibly distorted—several different dark colours have clipped to black. “Scan samples” reproduces sampled swatches for comparison, not calibrated physical colour.</p><a href="${sourceUrl(49)}" target="_blank" rel="noopener">View the colour table · PDF 49 / TO 00:10:10 ↗</a></aside>`;
 if(!item){
 main.innerHTML=folio+`<section class="colour-heading"><div><span class="eyebrow">02 / Heraldry & dress</span><h1>The manual,<br>in colour.</h1><p class="intro">Silver stars on a red banner. Gold division insignia. Tenne, Ultramarine and red duty tunics. Follow the colour codes hidden in the black-and-white sheets.</p></div><div class="colour-hero">${artwork(plates[3])}<span>SF03UC · GOLD<br>SF32UC · BLACK</span></div></section><div class="colour-toolbar"><div class="colour-filters" aria-label="Filter colour plates">${['all','flags','insignia','uniforms'].map(c=>`<button data-category="${c}" aria-pressed="${c==='all'}">${titleCase(c)}</button>`).join('')}</div>${modeControl}</div><div id="colour-status" class="colour-status" role="status">8 studies / named-colour reconstructions</div><div id="colour-grid" class="colour-grid"></div>${method}`;
 function gallery(){const list=plates.filter(x=>category==='all'||x.category===category),p=palette();main.querySelector('#colour-grid').innerHTML=list.map((x,i)=>`<a href="#/colours/${x.id}" class="colour-card"><div class="colour-card-art">${artwork(x)}<span class="colour-plate-no">${String(plates.indexOf(x)+1).padStart(2,'0')} / ${x.category.toUpperCase()}</span></div><div class="colour-card-copy"><h2>${x.title} <span>↗</span></h2><p>${x.sub}</p><div class="colour-mini">${x.codes.map(c=>`<i title="${names[c]} · ${c}UC" style="background:${p[c]}"></i>`).join('')}<span>TO ${x.to}</span></div></div></a>`).join('');paintArt(main.querySelector('#colour-grid'),p);main.querySelector('#colour-status').textContent=`${list.length} studies / ${mode==='scan'?'uncalibrated scan samples':'named-colour reconstructions'}`;}
 main.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;main.querySelectorAll('[data-category]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));gallery();});
 main.querySelector('#colour-mode').onchange=e=>{mode=e.target.value;gallery();main.querySelector('.colour-hero').innerHTML=artwork(plates[3])+'<span>SF03UC · GOLD<br>SF32UC · BLACK</span>';paintArt(main.querySelector('.colour-hero'),palette());};gallery();paintArt(main.querySelector('.colour-hero'),palette());
 }else{
 main.innerHTML=folio+`<div class="sheet-title"><div><span class="eyebrow">${item.category} / colour study</span><h1>${item.title}</h1></div><a class="btn outline" href="#/colours">All colour plates ↗</a></div><div class="colour-study"><section class="colour-stage"><div class="colour-toolbar">${modeControl}<button id="colour-download" class="icon-btn">Save PNG ↓</button></div><div id="colour-large"></div><div class="colour-stage-caption"><span id="render-caption">NAMED-COLOUR RECONSTRUCTION</span><span>COLOURISED FROM THE MANUAL SHEET · PDF ${item.page}</span></div></section><aside class="colour-particulars"><span class="eyebrow">The specification</span><p>${item.note}</p>${item.kind==='uniform'?`<div class="uniform-controls"><label>DIVISION<select id="uniform-division">${Object.entries(divisions).map(([id,d])=>`<option value="${id}" ${division===id?'selected':''}>${d.name}</option>`).join('')}</select></label><label>GRADE<select id="uniform-rank">${Object.keys(ranks).map(id=>`<option value="${id}">${titleCase(id)}</option>`).join('')}</select></label><p class="small">Front, side and back views are the manual’s own figures. Grade braid is cut from PDF 65 and placed above each cuff.</p></div>`:''}<div id="colour-specs"></div><div class="colour-source-links" id="colour-source-links"></div></aside></div><details class="colour-source"><summary>Compare with the original manual sheet</summary><img id="colour-source-image" src="${sourceUrl(item.page)}" alt="Original source drawing, PDF ${item.page}" loading="lazy"></details>${method}<div class="pagination"><a href="#/colours/${plates[(plates.indexOf(item)+plates.length-1)%plates.length].id}">← Previous plate</a><a href="#/colours">All colour plates</a><a href="#/colours/${plates[(plates.indexOf(item)+1)%plates.length].id}">Next plate →</a></div>`;
 function update(){const p=palette(),codes=item.kind==='uniform'?[divisions[division].code,'SF32',...(item.id==='female-duty'?['SF25']:[]),'SF03']:item.codes;main.querySelector('#colour-large').innerHTML=artwork(item,{division,rank});paintArt(main.querySelector('#colour-large'),p);main.querySelector('#colour-specs').innerHTML=swatches(codes,p);main.querySelector('#render-caption').textContent=mode==='scan'?'UNCALIBRATED SCAN-SAMPLE COLOURS':'NAMED-COLOUR RECONSTRUCTION';const page=item.page,to=item.to;main.querySelector('#colour-source-links').innerHTML=`<a href="${sourceUrl(page)}" target="_blank" rel="noopener">Source: PDF ${page} / TO ${to} ↗</a>${item.kind==='uniform'?`<a href="${sourceUrl(65)}" target="_blank" rel="noopener">Insignia & braid: PDF 65 ↗</a>`:''}<a href="${sourceUrl(49)}" target="_blank" rel="noopener">Colour specification: PDF 49 ↗</a>`;main.querySelector('#colour-source-image').src=sourceUrl(page);main.querySelector('#colour-source-image').alt=`Original manual source, PDF ${page}`;}
 main.querySelector('#colour-mode').onchange=e=>{mode=e.target.value;update();};
 if(item.kind==='uniform'){main.querySelector('#uniform-division').onchange=e=>{division=e.target.value;update();};main.querySelector('#uniform-rank').onchange=e=>{rank=e.target.value;update();};}
 main.querySelector('#colour-download').onclick=()=>{const c=main.querySelector('#colour-large canvas');if(!c)return;c.toBlob(b=>{const url=URL.createObjectURL(b);const a=document.createElement('a');a.href=url;a.download=`${item.id}-${item.kind==='uniform'?division+'-'+rank+'-':''}${mode}.png`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);},'image/png');};update();
 }
 function palette(){return mode==='scan'&&scan?Object.fromEntries(Object.entries(scan.colours).map(([k,v])=>[k,v.hex])):displayPalette;}
 fetch('assets/colours/palette-scan.json').then(r=>{if(!r.ok)throw Error('Palette unavailable');return r.json();}).then(data=>{if(!alive)return;scan=data;const option=main.querySelector('#colour-mode option[value="scan"]');option.disabled=false;option.textContent='Scan samples · uncalibrated';}).catch(()=>{if(alive)main.querySelector('#colour-mode option[value="scan"]').textContent='Scan samples unavailable';});
 return ()=>{alive=false;};
}
